            // of any other string
            for (int k = 0; k < strings.size(); k++) {
                if (k != i && strings.get(k).contains(String.valueOf(currentChar))) {
                    substringSize++;
                }
            }

            // Check if the substring size is larger than the current largest size
            if (substringSize > largestSubstringSize) {
                largestSubstringSize = substringSize;
            }
        }
    }

    // Return the largest substring size
    return largestSubstringSize;
