    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        visited.add(current[0] * n + current[1]);
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }
        for (int[] path : paths) {
            if (path[0] == current[0] && path[1] == current[1]) {
                queue.offer(new int[] {path[2], path[3]});
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a set to store the n-tersections that have been visited
    Set<Integer> visited = new HashSet<>();
    // Initialize a queue to store the n-tersections to be visited
    Queue<Integer> queue = new LinkedList<>();
    // Add the starting n-tersection to the queue
    queue.add(start[0] * n + start[1]);
    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the next n-tersection to be visited
        int cur = queue.poll();
        // Check if the current n-tersection is the ending n-tersection
        if (cur == end[0] * n + end[1]) {
            // If it is, return "can be travelled"
            return "can be travelled";
        }
        // If the current n-tersection has not been visited, mark it as visited and add its adjacent n-tersections to the queue
        if (!visited.contains(cur)) {
            visited.add(cur);
            for (int[] path : paths) {
                queue.add(path[0] * n + path[1]);
            }
        }
    }
    // If the queue is empty, the ending n-tersection cannot be reached
    return "cannot be travelled";
}

