    Set<String> visited = new HashSet<>();
    Deque<String> queue = new ArrayDeque<>();
    String startPoint = start[0] + "," + start[1];
    String endPoint = end[0] + "," + end[1];
    queue.offer(startPoint);
    visited.add(startPoint);
    while (!queue.isEmpty()) {
        String currentPoint = queue.poll();
        if (currentPoint.equals(endPoint)) {
            return "can be travelled";
        }
        for (int[] path : paths) {
            String neighborPoint = path[0] + "," + path[1];
            if (!visited.contains(neighborPoint)) {
