public static String convertDatesToWeekdays(String date) {
    String weekdays = "Sunday, Monday, Tuesday, Wednesday, Thursday, Friday, Saturday";
    int month = Integer.parseInt(date.substring(0, 2));
    int day = Integer.parseInt(date.substring(3, 5));
    int year = Integer.parseInt(date.substring(6));
    Calendar cal = Calendar.getInstance();
    cal.set(Calendar.MONTH, month - 1);
    cal.set(Calendar.DATE, day);
    cal.set(Calendar.YEAR, year);
    int dayOfWeek = cal.get(Calendar.DAY_OF_WEEK);
    return weekdays.substring(dayOfWeek - 1, dayOfWeek) + " " + date;
}

public static String convertDatesToWeekdays(String date) {
    String[] months = {"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"};
    String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};

    String[] dateParts = date.split(" ");
    int month = Integer.parseInt(dateParts[0]);
    int day = Integer.parseInt(dateParts[1]);
    int year = Integer.parseInt(dateParts[2]);

    int weekday = (int) ((26 * month / 10 + day + year + year / 4 + 6 * (year / 100) + year / 400) % 7);

    return months[month - 1] + " " + day + ", " + year + " is " + weekdays[weekday];
}

public static String convertDatesToWeekdays(String date) {
