public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Get the index of the 5% and 95% percentile
    int low = (int) Math.ceil(arr.length * 0.05);
    int high = (int) Math.floor(arr.length * 0.95);

    // Calculate the sum of the remaining elements
    double sum = 0;
    for (int i = low; i <= high; i++) {
        sum += arr[i];
    }

    // Return the average of the remaining elements
    return sum / (high - low + 1);
}

public double trimMean(int[] arr) {
    // Step 1: Sort the array
    Arrays.sort(arr);

    // Step 2: Find the 5% and 95% points of the array
    int start = (int) Math.ceil(arr.length * 0.05);
    int end = (int) Math.floor(arr.length * 0.95);

    // Step 3: Calculate the sum of the sorted array
    int sum = 0;
    for (int i = start; i < end; i++) {
        sum += arr[i];
    }

    // Step 4: Calculate the mean and return the result
    double mean = (double) sum / (end - start);
    return mean;
}

public double trimMean(int[] arr) {
    // sort the array in ascending order
    Arrays.sort(arr);

    // find the smallest 5% and largest 5% of the elements
    int smallest = (int) (arr.length * 0.05);
    int largest = (int) (arr.length * 0.95);

    // calculate the mean of the remaining elements after removing the smallest and largest 5%
    double sum = 0;
    for (int i = smallest; i < largest; i++) {
        sum += arr[i];
    }
    double mean = sum / (largest - smallest);

    // return the mean with an error within 10^-5
    return Math.round(mean * 100000) / 100000.0;
}

public double trimMean(int[] arr) {
    int n = arr.length;
