public boolean canArrange(int[] arr, int k) {
    Arrays.sort(arr);
    int n = arr.length;
    if (n % 2 == 1) return false;
    int[] sum = new int[n / 2];
    for (int i = 0; i < n; i += 2) {
        sum[i / 2] = arr[i] + arr[i + 1];
    }
    return canArrange(sum, k);
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    int[] counts = new int[k];
    for (int i = 0; i < n; i++) {
        counts[arr[i] % k]++;
    }
    int count = 0;
    for (int i = 0; i < k; i++) {
        if (counts[i] % 2 != 0) {
            count++;
        }
    }
    return count <= 1;
}

