public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int time = 0;
    boolean[] visited = new boolean[n];
    Deque<Integer> queue = new ArrayDeque<>();
    queue.offer(0);
    visited[0] = true;

    while (!queue.isEmpty()) {
        int node = queue.poll();
        time += hasApple[node] ? 2 : 1;

        for (int neighbor : findNeighbors(edges, node)) {
            if (!visited[neighbor]) {
                queue.offer(neighbor);
                visited[neighbor] = true;
            }
        }
    }

    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] parent = new int[n];
    for (int i = 0; i < n; i++) {
        parent[i] = i;
    }

    for (int[] edge : edges) {
        int u = edge[0], v = edge[1];
        parent[find(u)] = find(v);
    }

    int time = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            time++;
        }
        if (parent[i] == i) {
            time += 2;
        }
    }

    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] distances = new int[n];
    Arrays.fill(distances, Integer.MAX_VALUE);
    distances[0] = 0;
    for (int i = 0; i < n; i++) {
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            if (u != v && distances[u] != Integer.MAX_VALUE && (distances[v] == Integer.MAX_VALUE || distances[u] + 1 < distances[v])) {
                distances[v] = distances[u] + 1;
            }
        }
    }
    int totalTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i] && distances[i] != Integer.MAX_VALUE) {
            totalTime += distances[i];
        }
    }
    return totalTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] parent = new int[n];
    int[] depth = new int[n];
    int[] time = new int[n];
    int[][] graph = new int[n][n];
    for (int i = 0; i < edges.length; i++) {
        int u = edges[i][0];
        int v = edges[i][1];
        graph[u][v] = 1;
        graph[v][u] = 1;
    }
    for (int i = 0; i < hasApple.length; i++) {
        if (hasApple[i]) {
            time[i] = 1;
        }
    }
    for (int i = 0; i < n; i++) {
        if (i == 0) {
            dfs(i, parent, depth, graph, time);
        } else {
            if (!graph[0][i]) {
                dfs(i, parent, depth, graph, time);
            }
        }
    }
    int ans = 0;
    for (int i = 0; i < n; i++) {
        if (i != 0) {
            ans += time[i] * depth[i];
        }
    }
    return ans;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] visited = new int[n];
    int time = 0;
    int start = 0;
    while (visited[start] == 0) {
        visited[start] = 1;
        for (int i = 0; i < edges.length; i++) {
            int node = edges[i][0] == start ? edges[i][1] : edges[i][0];
            if (hasApple[node]) {
                time += 2;
            }
            if (visited[node] == 0) {
                visited[node] = 1;
                if (hasApple[node]) {
                    time += 2;
                }
                start = node;
                break;
            }
        }
    }
    return time;
}

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    StringBuilder result = new StringBuilder();
    while (chars.length > 0) {
        // pick the smallest character and append it to the result
        char smallest = chars[0];
        result.append(smallest);
        chars = Arrays.copyOfRange(chars, 1, chars.length);
        // pick the smallest character that is greater than the last appended character and append it to the result
        int smallestIndex = -1;
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] > smallest) {
                smallestIndex = i;
                break;
            }
        }
        if (smallestIndex != -1) {
            result.append(chars[smallestIndex]);
            chars = Arrays.copyOfRange(chars, 0, smallestIndex) + Arrays.copyOfRange(chars, smallestIndex + 1, chars.length);
        }
        // pick the largest character and append it to the result
        char largest = chars[chars.length - 1];
        result.append(largest);
        chars = Arrays.copyOfRange(chars, 0, chars.length - 1);
        // pick the largest character that is smaller than the last appended character and append it to the result
        int largestIndex = -1;
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] < largest) {
                largestIndex = i;
                break;
            }
        }
        if (largestIndex != -1) {
            result.append(chars[largestIndex]);
            chars = Arrays.copyOfRange(chars, 0, largestIndex) + Arrays.copyOfRange(chars, largestIndex + 1, chars.length);
        }
    }
    return result.toString();
}

