public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    int[] freq = new int[26];

    // Step 1: pick the smallest character from s and append it to the result
    int smallest = -1;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (freq[c - 'a'] == 0) {
            smallest = c;
            break;
        }
    }
    result.append(smallest);

    // Step 2: pick the smallest character from s which is greater than the last appended character to the result and append it
    while (smallest != -1) {
        int nextSmallest = -1;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c != smallest && freq[c - 'a'] == 0) {
                nextSmallest = c;
                break;
            }
        }
        if (nextSmallest != -1) {
            smallest = nextSmallest;
            result.append(smallest);
        } else {
            smallest = -1;
        }
    }

    // Step 3: repeat step 2 until you cannot pick more characters

    // Step 4: pick the largest character from s and append it to the result
    int largest = -1;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (largest == -1 || c > largest) {
            largest = c;
        }
    }
    result.append(largest);

    // Step 5: pick the largest character from s which is smaller than the last appended character to the result and append it
    while (largest != -1) {
        int nextLargest = -1;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < largest) {
                nextLargest = c;
                break;
            }
        }
        if (nextLargest != -1) {
            largest = nextLargest;
            result.append(largest);
        } else {
            largest = -1;
        }
    }

    // Step 6: repeat step 5 until you cannot pick more characters

    // Step 7: repeat the steps from 1 to 6 until you pick all characters from s
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (freq[c - 'a'] == 0) {
            result.append(c);
        }
    }

    return result.toString();
}

public String sortString(String s) {
  String result = "";
  // create a copy of the string to avoid modifying the original string
  String temp = s.substring(0);
