    int smallestIndex = findSmallestCharacter(temp);
    result += temp.charAt(smallestIndex);
    temp = temp.substring(0, smallestIndex) + temp.substring(smallestIndex + 1);

    // step 2: pick the smallest character that is greater than the last appended character
    int smallerThanLastAppendedIndex = findSmallerThanLastAppendedCharacter(temp, result.charAt(result.length() - 1));
    if (smallerThanLastAppendedIndex != -1) {
