public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);
    int prev = cost[0], curr = Math.min(cost[0], cost[1]);
    for (int i = 2; i < n; i++) {
        int next = Math.min(prev + cost[i], curr + cost[i - 1]);
        prev = curr;
        curr = next;
    }
    return curr;
}

public int minCostClimbingStairs(int[] cost) {
    int prevPrev = cost[0];
    int prev = cost[1];
    int minCost = Math.min(prevPrev, prev);
    for (int i = 2; i < cost.length; i++) {
        int currentCost = cost[i];
        minCost = Math.min(minCost, prevPrev + currentCost);
        int tmp = prevPrev;
        prevPrev = prev;
        prev = currentCost + Math.min(prev, tmp);
    }
    return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 1) return cost[0];
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(cost[i] + dp[i-2], cost[i] + dp[i-1]);
    }
    return Math.min(dp[n-1], dp[n-2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int dp0 = cost[0];
    int dp1 = cost[1];
    for (int i = 2; i < n; i++) {
        int temp = Math.min(dp0, dp1);
        dp0 = dp1;
        dp1 = temp + cost[i];
    }
    return Math.min(dp0, dp1);
}

public int minCostClimbingStairs(int[] cost) {
    int minCost = 0;
    for (int i = 0; i < cost.length - 1; i++) {
        minCost = Math.min(minCost, cost[i]);
    }
    return minCost;
}

