public String makeGood(String s) {
    StringBuilder sb = new StringBuilder();
    // Iterate through the string and keep track of the index of the last removed character
    int lastRemoved = -1;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        // If the current character is lowercase and the previous character is its corresponding uppercase
        // or if the current character is uppercase and the previous character is its corresponding lowercase
        if ((c >= 'a' && c <= 'z' && i > 0 && s.charAt(i - 1) - c == 32) || (c >= 'A' && c <= 'Z' && i > 0 && s.charAt(i - 1) - c == -32)) {
            // If the last removed character is not the previous character, append it to the string
            if (lastRemoved != i - 1) {
                sb.append(s.charAt(i - 1));
                lastRemoved = i - 1;
            }
        } else {
            // Otherwise, append the current character to the string
            sb.append(c);
        }
    }
    return sb.toString();
}

public int maxUniqueSplit(String s) {
