    for (int i = 1; i <= s.length(); i++) {
        for (int j = 0; j + i - 1 < s.length(); j++) {
            String substr = s.substring(j, j + i);
            if (!set.contains(substr)) {
                set.add(substr);
                max = Math.max(max, set.size());
            }
        }
    }
