}

public int maxUniqueSplit(String s) {
    int[] counts = new int[26];
    for (int i = 0; i < s.length(); i++) {
        counts[s.charAt(i) - 'a']++;
    }
    int numUnique = 0;
    for (int i = 0; i < 26; i++) {
        if (counts[i] != 0) {
            numUnique++;
        }
    }
    int maxUnique = Math.min(numUnique, s.length());
    for (int i = 1; i < s.length() - 1; i++) {
        if (counts[s.charAt(i) - 'a'] == 1) {
            int maxUniqueLeft = maxUniqueSplit(s.substring(0, i)) + 1;
            int maxUniqueRight = maxUniqueSplit(s.substring(i + 1));
            maxUnique = Math.max(maxUnique, maxUniqueLeft + maxUniqueRight);
        }
    }
    return maxUnique;
}

