public static String getSmallestString(int n, int k) {
    String alphabet = "abcdefghijklmnopqrstuvwxyz";
    StringBuilder sb = new StringBuilder();
    int i = 0;
    while (k > 0 && i < n) {
        int charValue = k % 26;
        sb.append(alphabet.charAt(charValue - 1));
        k = (k - charValue) / 26;
        i++;
    }
    return sb.reverse().toString();
}

public String getSmallestString(int n, int k) {
    char[][] grid = new char[n][n];
    int currPos = 1;
    for (int row = 0; row < n; row++) {
        for (int col = 0; col <= row; col++) {
            grid[row][col] = (char) (currPos + 'a' - 1);
            currPos += n - row;
        }
    }
    int remain = k - (n * (n + 1) / 2);
    while (remain > 0) {
        for (int row = 0; row < n; row++) {
            if (grid[row][0] < n) {
                grid[row][0]++;
                remain--;
            }
        }
        for (int row = 1; row < n; row++) {
            if (grid[row][row] - grid[row - 1][row - 1] > remain) {
                grid[row][row - 1] += remain - 1;
                remain = 0;
                break;
            } else {
                grid[row][row - 1] += remain;
                remain -= grid[row][row - 1] - grid[row - 1][row - 1];
            }
        }
    }
    StringBuilder sb = new StringBuilder();
    for (int row = 0; row < n; row++) {
        for (int col = 0; col <= row; col++) {
            sb.append(grid[row][col]);
        }
    }
    return sb.toString();
}

