    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int length = 1;
                // Check horizontal line
                for (int k = j + 1; k < n; k++) {
                    if (mat[i][k] == 1) {
                        length++;
                    } else {
                        break;
                    }
                }
                // Check vertical line
                for (int k = i + 1; k < m; k++) {
                    if (mat[k][j] == 1) {
                        length++;
                    } else {
                        break;
                    }
                }
                // Check diagonal line
                for (int k = j + 1, l = i + 1; k < n && l < m; k++, l++) {
                    if (mat[l][k] == 1) {
                        length++;
                    } else {
                        break;
                    }
                }
                // Check anti-diagonal line
                for (int k = j + 1, l = i - 1; k < n && l >= 0; k++, l--) {
                    if (mat[l][k] == 1) {
                        length++;
                    } else {
