public int squarePermutations(int[] A) {
    Map<Integer, List<int[]>> squareLists = new HashMap<>();
    int n = A.length;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int square = (int) Math.sqrt(A[i] * A[j]);
            if (square == (A[i] * A[j]) / square) {
                if (!squareLists.containsKey(square)) {
                    squareLists.put(square, new ArrayList<>());
                }
                squareLists.get(square).add(new int[]{A[i], A[j]});
            }
        }
    }
    int permutations = 0;
    for (List<int[]> list : squareLists.values()) {
        permutations += list.size() * (list.size() - 1) / 2;
    }
    return permutations;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    int[] permutations = new int[n];
    int[][] products = new int[n][n];
    for (int i = 0; i < n; i++) {
        permutations[i] = 1;
        for (int j = i + 1; j < n; j++) {
            int product = A[i] * A[j];
            products[i][j] = product;
            products[j][i] = product;
        }
    }
    int count = 0;
    for (int i = 0; i < n; i++) {
        int pi = permutations[i];
        for (int j = i + 1; j < n; j++) {
            int pj = permutations[j];
            int product = products[i][j];
            int sum = pi + pj;
            if (sum == 0 || sum == 1) {
                count += 1;
            } else if (sum == 2) {
                count += 2 * products[i][j];
            } else {
                for (int k = j + 1; k < n; k++) {
                    if (pi * permutations[k] == pj * products[i][j]) {
                        count += 4 * permutations[k];
                    }
                }
            }
        }
    }
    return count;
}

