}

public static int squarePermutations(int[] A) {
    int n = A.length;
    int[][] dp = new int[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) {
                dp[i][j] = 1;
            } else if (A[i] + A[j] <= 100 && (A[i] + A[j]) % 2 == 0) {
                dp[i][j] = dp[j][i];
            } else {
                dp[i][j] = 0;
            }
        }
    }
    return dp[n - 1][0];
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    int[][] dp = new int[n][n];
    for (int i = 0; i < n; i++) {
        dp[i][i] = 1;
    }
    for (int k = 0; k < n - 1; k++) {
        for (int i = 0; i < n - k - 1; i++) {
            int j = i + k + 1;
            for (int m = i; m <= j; m++) {
                int x = (int) Math.sqrt(A[i] + A[m]);
                if (x * x == A[i] + A[m]) {
                    dp[i][j] += dp[i][m] * dp[m + 1][j];
                }
            }
        }
    }
    return dp[0][n - 1];
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] leftMax = new int[n];
    int[] rightMax = new int[n];
    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        int height = heights[i];
        if (i == 0) {
            leftMax[i] = height;
        } else {
            leftMax[i] = Math.max(height, leftMax[i - 1]);
        }
        if (i == n - 1) {
            rightMax[i] = height;
        } else {
            rightMax[i] = Math.max(height, rightMax[i + 1]);
        }
        int width = Math.min(leftMax[i], rightMax[i]);
        maxArea = Math.max(maxArea, height * width);
    }
    return maxArea;
}

