    for (int i = 1; i < n; i++) {
        int p = i - 1;
        while (p >= 0 && heights[p] >= heights[i]) p = left[p];
        left[i] = p;
    }
    for (int i = n-2; i >= 0; i--) {
        int p = i + 1;
        while (p < n && heights[p] >= heights[i]) p = right[p];
        right[i] = p;
    }
    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, heights[i] * (right[i] - left[i] - 1));
