public static int[] diagonalOrder(int[][] mat) {
    int n = mat.length;
    int m = mat[0].length;
    int[] result = new int[n * m];
    int curr = 0;
    for (int i = 0; i < n + m - 1; i++) {
        int startRow = Math.max(0, i - m + 1);
        int startCol = Math.max(0, m - 1 - i);
        int endRow = Math.min(i, n - 1);
        int endCol = Math.min(i, m - 1);
        if (startRow == endRow && startCol == endCol) {
            result[curr++] = mat[startRow][startCol];
        } else if (startRow == endRow) {
            for (int col = startCol; col <= endCol; col++) {
                result[curr++] = mat[startRow][col];
            }
        } else if (startCol == endCol) {
            for (int row = startRow; row <= endRow; row++) {
                result[curr++] = mat[row][startCol];
            }
        } else {
            int stepRow = startRow < endRow ? 1 : -1;
            int stepCol = startCol < endCol ? 1 : -1;
            while (startRow != endRow || startCol != endCol) {
                result[curr++] = mat[startRow][startCol];
                startRow += stepRow;
                startCol += stepCol;
            }
        }
    }
    return result;
}

