    }
    int a = matrix[1][0] * matrix[2][1] + matrix[2][0] * matrix[0][1] + matrix[0][0] * matrix[1][1];
    int b = matrix[1][1] * matrix[2][0] + matrix[2][1] * matrix[0][0] + matrix[0][1] * matrix[1][0];
    if (a == 0 && b == 0) return false;
    double c = a * matrix[0][0] + b * matrix[0][1];
    return (c * c) % 1000000007 == 0;
}

