public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        return false;
    }
    int[] v1 = new int[]{points[1][0] - points[0][0], points[1][1] - points[0][1]};
    int[] v2 = new int[]{points[2][0] - points[1][0], points[2][1] - points[1][1]};
    int[] v3 = new int[]{points[0][0] - points[2][0], points[0][1] - points[2][1]};
    return v1[0] * v2[1] == v1[1] * v2[0] && v1[0] * v3[1] == v1[1] * v3[0] && v2[0] * v3[1] == v2[1] * v3[0];
