public static int calculateEnergy(String s) {
    int energy = 1;
    char prevChar = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char currChar = s.charAt(i);
        if (currChar == prevChar) {
            energy++;
        } else {
            energy = 1;
        }
        prevChar = currChar;
    }
    return energy;
}

public static int calculateEnergy(String s) {
    char[] chars = s.toCharArray();
    int start = 0, end = 0, maxLen = 0, currentLen = 0;

    while (end < chars.length) {
        if (start < end && chars[start] != chars[end]) {
            start++;
        } else {
            currentLen = end - start + 1;
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            end++;
        }
    }

    return maxLen;
}

public static int calculateEnergy(String s) {
    int windowStart = 0;
    int maxLength = 0;
    Map<Character, Integer> charMap = new HashMap<>();

    for (int windowEnd = 0; windowEnd < s.length(); windowEnd++) {
        char currentChar = s.charAt(windowEnd);

        if (charMap.containsKey(currentChar)) {
            windowStart = Math.max(charMap.get(currentChar) + 1, windowStart);
        }

        charMap.put(currentChar, windowEnd);
        maxLength = Math.max(maxLength, windowEnd - windowStart + 1);
    }

    return maxLength;
}

public static int calculateEnergy(String s) {
    int energy = 1;
    char prevChar = s.charAt(0);
    int maxEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        char currChar = s.charAt(i);
        if (currChar == prevChar) {
            energy++;
            maxEnergy = Math.max(maxEnergy, energy);
        } else {
            energy = 1;
            prevChar = currChar;
        }
    }

    return maxEnergy;
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLength = 0;
    int currentLength = 0;
    char currentChar = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == currentChar) {
            currentLength++;
        } else {
            if (currentLength > maxLength) {
                maxLength = currentLength;
            }
            currentLength = 1;
            currentChar = s.charAt(i);
        }
    }
    if (currentLength > maxLength) {
        maxLength = currentLength;
    }
    return maxLength;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        result.add(i);
    }
    for (int i = 10; i <= n; i *= 10) {
        int digit = i % 10;
        int upper = i * 10 - 1;
        for (int j = upper; j >= i && j <= n; j /= 10) {
            if (j % 10 == digit) {
                result.add(j);
            }
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        result.add(i);
    }
    for (int i = 10; i <= n; i++) {
        if (i % 10 == 0) continue;
        result.add(i);
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> lexicographicalOrder = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
      lexicographicalOrder.add(i);
    }
    Collections.sort(lexicographicalOrder, new Comparator<Integer>() {
      @Override
      public int compare(Integer a, Integer b) {
        String sa = String.valueOf(a);
        String sb = String.valueOf(b);
        return sa.compareTo(sb);
      }
    });
    return lexicographicalOrder;
  }

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i = result.get(result.size() - 1) + 1) {
        result.add(i);
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    Collections.sort(result, new Comparator<Integer>() {
        @Override
        public int compare(Integer a, Integer b) {
            String s1 = String.valueOf(a) + String.valueOf(b);
            String s2 = String.valueOf(b) + String.valueOf(a);
            return s1.compareTo(s2);
        }
    });
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueNums = new HashSet<>();
    for (int num : nums) {
        uniqueNums.add(num);
    }
    int sum = 0;
    for (int num : uniqueNums) {
        sum += num;
    }
    return sum;
}

public static int calculateUniqueSum(int[] nums) {
    int sum = 0;
    for (int i = 0; i < nums.length; i++) {
        boolean isUnique = true;
        for (int j = 0; j < i; j++) {
            if (nums[i] == nums[j]) {
                isUnique = false;
                break;
            }
        }
        if (isUnique) {
            sum += nums[i];
        }
    }
    return sum;
}

