public static int minPerfectSquareSum(int n) {
    int count = 0;
    while (n > 0) {
        int i = 1;
        while (i * i <= n) {
            i++;
        }
        n -= i * i - i;
        count++;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    int sum = 0;
    int i = 1;
    while (sum < n) {
        count++;
        sum += i * i;
        i++;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int sum = 0;
    int count = 0;
    for (int i = 1; sum <= n; i++) {
        sum += i * i;
        count++;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int minSquares = 0;
    int currentSquare = 1;
    while (currentSquare <= n) {
        minSquares++;
        currentSquare = currentSquare * currentSquare;
    }
    return minSquares;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    while (n > 0) {
        double squareRoot = Math.sqrt(n);
        count++;
        n -= squareRoot;
        n = (int) Math.ceil(squareRoot);
    }
    return count;
}

